SELECT DISTINCT
BEN_PLN.REC_SRC_CD AS REC_SRC_CD
,'CA5' AS HEALTH_PLAN_CODE
, CASE WHEN BEN_PLN.BENFT_PLN_ID in ('A0061MASWMNP01','A0061MASWMNP02','A0061MASWMNP03','A0061MASWMNP04','A0061MASWMNP05','A0061MASWMNP06','A0061MASWMNP07','A0061MASWNEP08','A0061MASWNEP09','A0061MASWSDP10','A0061MASWSDP11','A0061MASWSDP12','A0061MASWNEP13','A0061MASWMNS01','A0061MASWSDP15','A0061MASWSDP16') THEN 'PCA5-4911' WHEN BEN_PLN.BENFT_PLN_ID in ('A0061MGASWMNP05','A0061MGASWMNP02','A0061MGASWMNP12') THEN 'PCA5-4913' WHEN BEN_PLN.BENFT_PLN_ID in ('A0061MASWNDP14') THEN 'PCA5-5240' WHEN BEN_PLN.BENFT_PLN_ID in ('C01475_0001','C01475_0002','C01475_0004','C01475_0005','C01475_0010') THEN 'PCA5-5242' ELSE 'PCA5-4913' END AS PROGRAM_CODE
, SUBSTR(MFV.SBSCR_ID,1,10)   AS MBR_ID
,MBR_ID AS MBR_ID_2
,MBR_CURR_VU.FNAME AS MBR_FIRST_NAME
,MBR_CURR_VU.MNAME AS MBR_MIDDLE_NAME
,MBR_CURR_VU.LNAME AS MBR_LAST_NAME
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_1_TXT IS NULL THEN UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_RES_CURR_ADDR_LN_1_TXT,1,40),',','')) ELSE UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_1_TXT,1,40),',','')) END  AS MBR_ADDR_1
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_2_TXT IS NULL THEN UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_RES_CURR_ADDR_LN_2_TXT,1,40),',','')) ELSE UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_2_TXT,1,40),',','')) END AS MBR_ADDR_2
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_CITY_NME IS NULL THEN UPPER(MFV.MBR_PHYS_ADDR_RES_CURR_CITY_NME) ELSE UPPER(MFV.MBR_PHYS_ADDR_MAIL_CURR_CITY_NME) END     AS MBR_CITY
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ST_SRC_CD IS NULL THEN UPPER(MFV.MBR_PHYS_ADDR_RES_CURR_ST_SRC_CD) ELSE UPPER(MFV.MBR_PHYS_ADDR_MAIL_CURR_ST_SRC_CD) END AS MBR_STATE
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ZIP_5_CD IS NULL THEN UPPER(MFV.MBR_PHYS_ADDR_RES_CURR_ZIP_5_CD) ELSE UPPER(MFV.MBR_PHYS_ADDR_MAIL_CURR_ZIP_5_CD) END AS MBR_ZIPCODE
,NULL AS GROUP_NUMBER
, TO_CHAR(MBR_CURR_VU.DOB, 'MM/DD/YYYY')   AS INITIAL_ACTIVATION_CODE
, CASE WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNP01' THEN '8201' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNP02' THEN '8202' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNP03' THEN '8203' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNP04' THEN '8204' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNP05' THEN '8205' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNP06' THEN '8206' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNP07' THEN '8207' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWNEP08' THEN '8208' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWNEP09' THEN '8209' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWSDP10' THEN '8210' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWSDP11' THEN '8211' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWSDP12' THEN '8212' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWNEP13' THEN '8213' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MASWMNS01' THEN '8214' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MGASWMNP05' THEN '8215' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MGASWMNP02' THEN '8161' WHEN BEN_PLN.BENFT_PLN_ID ='A0061MGASWMNP12' THEN '9224'  WHEN BEN_PLN.BENFT_PLN_ID = 'A0061MASWSDP15' THEN '51090' WHEN BEN_PLN.BENFT_PLN_ID = 'A0061MASWSDP16' THEN  '51091' WHEN BEN_PLN.BENFT_PLN_ID in ('A0061MASWNDP14') THEN '51093' WHEN BEN_PLN.BENFT_PLN_ID = 'C01475_0001' THEN '51094' WHEN BEN_PLN.BENFT_PLN_ID = 'C01475_0002' THEN '51095' WHEN BEN_PLN.BENFT_PLN_ID = 'C01475_0004' THEN '51096' WHEN BEN_PLN.BENFT_PLN_ID = 'C01475_0005' THEN '51097' WHEN BEN_PLN.BENFT_PLN_ID = 'C01475_0010' THEN '51098' END AS PACKAGE_ID
, CASE WHEN MFV.PHONE_TYP_COMN_CD_1 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END WHEN MFV.PHONE_TYP_COMN_CD_1 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END WHEN MFV.PHONE_TYP_COMN_CD_1 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END WHEN MFV.PHONE_TYP_COMN_CD_1 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END ELSE '9999999999' END AS MBR_PHONE
,BEN_PLN.BENFT_PLN_NME AS USER_DEFINED_FIELD_1
 FROM DFDS.DFDS_MBR_FULL_VU MFV INNER JOIN BASE_DS.BASE_DS_BENFT_PLN_CORE_VU BEN_PLN ON MFV.BENFT_PLN_KEY=BEN_PLN.BENFT_PLN_KEY LEFT JOIN BASE_DS.BASE_DS_MBR_TIME_LN_CURR_VU MBR_CURR_VU ON MFV.MBR_KEY=MBR_CURR_VU.MBR_KEY JOIN CIM.BENFT_PLN_EFCTV BPEF ON BPEF.BENFT_PLN_KEY = MFV.BENFT_PLN_KEY AND (to_varchar('1/1/2026') BETWEEN BPEF.EFCTV_DT and BPEF.EXPIR_DT OR CURRENT_DATE BETWEEN BPEF.EFCTV_DT and BPEF.EXPIR_DT) AND BPEF.ACTV_INDC = 1
WHERE BEN_PLN.BENFT_PLN_ID IN ('A0061MASWMNP01','A0061MASWMNP02','A0061MASWMNP03','A0061MASWMNP04','A0061MASWMNP05','A0061MASWMNP06','A0061MASWMNP07','A0061MASWNEP08','A0061MASWNEP09','A0061MASWSDP10','A0061MASWSDP11','A0061MASWSDP12','A0061MASWNEP13','A0061MASWMNS01','A0061MGASWMNP05','A0061MGASWMNP02','A0061MGASWMNP12','A0061MASWSDP15','A0061MASWSDP16','A0061MASWNDP14','C01475_0001','C01475_0002','C01475_0004','C01475_0005','C01475_0010') AND BEN_PLN.REC_SRC_CD IN ('HR2','CONVEY', 'HRCATE') AND (((BPEF.EXPIR_DT >=CURRENT_DATE AND BPEF.EFCTV_DT <= CURRENT_DATE) OR BPEF.EFCTV_DT = ADD_MONTHS(CURRENT_DATE,1) OR BPEF.EFCTV_DT BETWEEN CURRENT_DATE AND CURRENT_DATE + 1*30) OR to_varchar('1/1/2026') BETWEEN BPEF.EFCTV_DT AND BPEF.EXPIR_DT) AND YEAR(BPEF.EXPIR_DT)>2023 AND MFV.EFCTV_DT >= '1/1/2024' AND MFV.EFCTV_DT < MFV.EXPIR_DT AND MFV.EFCTV_DT <= CURRENT_DATE+15 AND MFV.EXPIR_DT > CURRENT_DATE

UNION ALL

SELECT DISTINCT
MFV.REC_SRC_CD AS REC_SRC_CD
,'CA5' AS HEALTH_PLAN_CODE
,CASE WHEN MFV.GRP_NBR in (07592, 07800, 07850, 07854, 07860, 07864, 07874, 07876, 07879, 07881, 07884, 07885, 07886, 07887, 07888, 07889) THEN 'PCA5-5240' ELSE 'PCA5-4913' END AS PROGRAM_CODE
, CASE WHEN MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1 IS NOT NULL THEN SUBSTR(MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1,1,9) ELSE SUBSTR(MFV.SBSCR_ID,1,9) END  AS MBR_ID
, CASE WHEN MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1 IS NOT NULL THEN MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1 ELSE SPLIT_PART(MBR_ID,'|',1) END  AS MBR_ID_2
,MBR_CURR_VU.FNAME AS MBR_FIRST_NAME
,MBR_CURR_VU.MNAME AS MBR_MIDDLE_NAME
,MBR_CURR_VU.LNAME AS MBR_LAST_NAME
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_1_TXT IS NULL THEN UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_RES_CURR_ADDR_LN_1_TXT,1,40),',','')) ELSE UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_1_TXT,1,40),',','')) END  AS MBR_ADDR_1
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_2_TXT IS NULL THEN UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_RES_CURR_ADDR_LN_2_TXT,1,40),',','')) ELSE UPPER(REPLACE(SUBSTR(MFV.MBR_PHYS_ADDR_MAIL_CURR_ADDR_LN_2_TXT,1,40),',','')) END AS MBR_ADDR_2
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_CITY_NME IS NULL THEN UPPER(MFV.MBR_PHYS_ADDR_RES_CURR_CITY_NME) ELSE UPPER(MFV.MBR_PHYS_ADDR_MAIL_CURR_CITY_NME) END     AS MBR_CITY
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ST_SRC_CD IS NULL THEN UPPER(MFV.MBR_PHYS_ADDR_RES_CURR_ST_SRC_CD) ELSE UPPER(MFV.MBR_PHYS_ADDR_MAIL_CURR_ST_SRC_CD) END AS MBR_STATE
, CASE WHEN MFV.MBR_PHYS_ADDR_MAIL_CURR_ZIP_5_CD IS NULL THEN UPPER(MFV.MBR_PHYS_ADDR_RES_CURR_ZIP_5_CD) ELSE UPPER(MFV.MBR_PHYS_ADDR_MAIL_CURR_ZIP_5_CD) END AS MBR_ZIPCODE
,TO_CHAR(MFV.GRP_NBR) AS GROUP_NUMBER
, TO_CHAR(MBR_CURR_VU.DOB, 'MM/DD/YYYY')   AS INITIAL_ACTIVATION_CODE
, CASE WHEN MFV.GRP_NBR in (70007, 70127, 70152, 70164, 70166, 70169, 70173, 70178, 70185, 70186, 70188, 70189, 70193, 70197, 70198, 70533, 70542,70589,70625,70628,70640,70668,70701,70702, 70703, 70705, 70711, 70713, 70715, 70717, 70719, 70819) THEN '8217' WHEN MFV.GRP_NBR in (70101, 70109, 70123, 70138, 70150, 70151, 70153, 70162, 70165, 70179, 70180, 70181, 70183, 70184, 70192, 70196, 70503, 70508, 70511, 70514, 70516, 70519, 70522, 70524, 70525, 70530, 70531, 70535, 70536, 70538, 70552, 70590, 70591, 70603, 70604, 70609, 70612, 70620, 70632, 70635, 70636, 70661,70678, 70684, 70692, 70801, 70818, 70854, 70873, 70876) THEN '8162'WHEN MFV.GRP_NBR in (07592, 07800, 07850, 07854, 07860, 07864, 07874, 07876, 07879, 07881, 07884, 07885, 07886, 07887, 07888, 07889) THEN '51092' WHEN MFV.GRP_NBR = 70191 THEN '9092' END AS PACKAGE_ID
, CASE WHEN MFV.PHONE_TYP_COMN_CD_1 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='HOME PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END WHEN MFV.PHONE_TYP_COMN_CD_1 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='MOBILE PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END WHEN MFV.PHONE_TYP_COMN_CD_1 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END WHEN MFV.PHONE_TYP_COMN_CD_1 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_1 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_1 END WHEN MFV.PHONE_TYP_COMN_CD_2 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_2 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_2 END WHEN MFV.PHONE_TYP_COMN_CD_3 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_3 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_3 END WHEN MFV.PHONE_TYP_COMN_CD_4 ='WORK PHONE' THEN CASE WHEN MFV.PHONE_NBR_4 = 0 THEN '9999999999' ELSE MFV.PHONE_NBR_4 END ELSE '9999999999' END AS MBR_PHONE
,TO_CHAR(LPAD(MFV.GRP_NBR,5,0)) AS USER_DEFINED_FIELD_1
 FROM DFDS.DFDS_MBR_FULL_VU MFV INNER JOIN BASE_DS.BASE_DS_BENFT_PLN_CORE_VU BEN_PLN ON MFV.BENFT_PLN_KEY=BEN_PLN.BENFT_PLN_KEY LEFT JOIN BASE_DS.BASE_DS_MBR_TIME_LN_CURR_VU MBR_CURR_VU ON MFV.MBR_KEY=MBR_CURR_VU.MBR_KEY
 WHERE MFV.GRP_NBR IN   (70007, 70127, 70152, 70164, 70166, 70169, 70173, 70178, 70185, 70186, 70188, 70189, 70193, 70197, 70198, 70533, 70542,70589,70625,70628,70640,70668,70701,70702, 70703, 70705, 70711, 70713, 70715, 70717, 70719, 70819, 70101, 70109, 70123, 70138, 70150, 70151, 70153, 70162, 70165, 70179, 70180, 70181, 70183, 70184, 70192, 70196, 70503, 70508, 70511, 70514, 70516, 70519, 70522, 70524, 70525, 70530, 70531, 70535, 70536, 70538, 70552, 70590, 70591, 70603, 70604, 70609, 70612, 70620, 70632, 70635, 70636, 70661,70678, 70684, 70692, 70801, 70818, 70854, 70873, 70876, 07592, 07800, 07850, 07854, 07860, 07864, 07874, 07876, 07879, 07881, 07884, 07885, 07886, 07887, 07888, 07889, 70191) AND MFV.REC_SRC_CD IN ('COSMOS') AND(((MFV.GRP_EFCTV_EXPIR_DT >=CURRENT_DATE AND MFV.GRP_EFCTV_EFCTV_DT <= CURRENT_DATE) OR MFV.GRP_EFCTV_EFCTV_DT = ADD_MONTHS(CURRENT_DATE,1) OR MFV.GRP_EFCTV_EFCTV_DT BETWEEN CURRENT_DATE AND CURRENT_DATE + 1*30) OR CURRENT_DATE BETWEEN MFV.GRP_EFCTV_EFCTV_DT AND MFV.GRP_EFCTV_EXPIR_DT) AND YEAR(MFV.GRP_EFCTV_EXPIR_DT)>2023 AND MFV.EFCTV_DT >= '1/1/2024' AND MFV.EFCTV_DT < MFV.EXPIR_DT AND MFV.EFCTV_DT <= CURRENT_DATE+15 AND MFV.EXPIR_DT > CURRENT_DATE;
